require_once __DIR__.'/../includes/auth.php';auth_require();require_once __DIR__.'/../includes/listing.php';$error='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST')try{
 $date=finance_date((string)($_POST['payment_date']??date('Y-m-d')));$key=(string)($_POST['request_key']??'');switch($_POST['action']??''){
 case 'approve_account':funds_create(trim((string)($_POST['name']??'')),(string)($_POST['kind']??''),(string)($_POST['currency_code']??''),$_POST['opening']??0,$key);break;
 case 'create_debt_receipt':finance_settle_debt((int)($_POST['debt_id']??0),(int)($_POST['cash_account_id']??0),$_POST['amount']??0,$date,$key,(string)($_POST['notes']??''));break;
 case 'create_purchase_payment':finance_pay_purchase((int)($_POST['purchase_id']??0),(int)($_POST['cash_account_id']??0),$_POST['amount']??0,$date,$key);break;
 case 'create_expense_payment':finance_pay_expense((int)($_POST['expense_id']??0),(int)($_POST['cash_account_id']??0),$_POST['amount']??0,$date,$key);break;
 case 'create_supplier_refund':finance_receive_supplier_refund((int)($_POST['purchase_id']??0),(int)($_POST['cash_account_id']??0),$_POST['amount']??0,$date,$key);break;
 case 'approve_refund':sale_refund_pay((int)($_POST['refund_id']??0),(int)($_POST['cash_account_id']??0),$_POST['amount']??0,$key,$date);break;
 case 'approve_transfer':if(isset($_POST['destination'])){if(!preg_match('/^(\d+):(\d+)$/D',(string)$_POST['destination'],$chosen))throw new InvalidArgumentException('Select a destination account.');$_POST['destination_branch']=$chosen[1];$_POST['destination_account']=$chosen[2];}funds_transfer((int)($_POST['cash_account_id']??0),(int)($_POST['destination_account']??0),(int)($_POST['destination_branch']??0),$_POST['amount']??0,$date,$key);break;
 default:throw new InvalidArgumentException('Unknown treasury action.');}redirect(BASE_URL.'modules/treasury.php');
}catch(Throwable $e){http_response_code(in_array($e->getCode(),[403,429],true)?$e->getCode():422);$error=public_error($e);}
$sorts=['newest'=>['t.id DESC','Newest first','تازه‌ترین اول'],'oldest'=>['t.id ASC','Oldest first','قدیمی‌ترین اول'],'date'=>['t.payment_date DESC,t.id DESC','Payment date','تاریخ پرداخت']];[$list,$history]=listing_query($pdo,'SELECT t.*,a.name FROM fund_transactions t JOIN fund_accounts a ON a.id=t.account_id AND a.shop_id=t.shop_id WHERE t.shop_id=?',[shop_id()],$sorts);$pageTitle=__t('Cash & bank','صندوق و بانک','نغدې او بانک');require __DIR__.'/../includes/header.php';
function payment_common(){echo csrf_field().'<input type="hidden" name="request_key" value="'.bin2hex(random_bytes(16)).'">';funds_select();echo '<label>'.__t('Amount','مبلغ','مبلغ').'<input class="form-control" name="amount" type="number" min="0.01" step="0.01" required></label><label>'.__t('Date','تاریخ','نېټه').'<input class="form-control" name="payment_date" type="date" value="'.date('Y-m-d').'" required></label>';}
?>
<h1><?= sanitize($pageTitle) ?></h1><?php if($error):?><p class="alert alert-danger" role="alert"><?= sanitize($error) ?></p><?php endif ?><div class="branch-grid"><?php $q=$pdo->prepare("SELECT * FROM fund_accounts WHERE shop_id=? AND status='active' ORDER BY name");$q->execute([shop_id()]);foreach($q->fetchAll() as $a):?><section class="card modern-form"><h3><?= sanitize($a['name'].' #'.$a['id']) ?></h3><strong><?= sanitize(funds_balance((int)$a['id']).' '.$a['currency_code']) ?></strong><p><?= $a['kind']==='cash'?__t('Cash account','حساب نقدی','نغدي حساب'):__t('Bank account','حساب بانکی','بانکي حساب') ?></p></section><?php endforeach ?></div>
<section class="card modern-form"><details><summary><?= __t('Create account & declare opening balance','ساخت حساب و ثبت ماندهٔ آغاز','حساب او لومړنۍ پیسې') ?></summary><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="approve_account"><input type="hidden" name="request_key" value="<?= bin2hex(random_bytes(16)) ?>"><div class="form-grid"><label><?= __t('Account name','نام حساب','د حساب نوم') ?><input class="form-control" name="name" maxlength="100" required></label><label><?= __t('Type','نوع حساب','ډول') ?><select class="form-control" name="kind"><option value="cash"><?= __t('Cash','نقدی','نغدې') ?></option><option value="bank"><?= __t('Bank','بانک','بانک') ?></option></select></label><label><?= __t('Currency','ارز','اسعار') ?><?= currency_select('currency_code') ?></label><label><?= __t('Verified opening amount','ماندهٔ آغاز تأییدشده','تایید شوې لومړنۍ پیسې') ?><input class="form-control" type="number" min="0" step="0.01" name="opening" value="0" required></label></div><p><?= __t('This is a declared opening balance, not reconstructed historical cash.','این رقم ماندهٔ اعلام‌شدهٔ آغاز است؛ پول تاریخی از روی معلومات قبلی حدس زده نمی‌شود.','دا اعلان شوې لومړنۍ پیسې دي، تاریخي اټکل نه دی.') ?></p><button class="btn btn-primary"><?= __t('Create account','ساخت حساب','حساب جوړ کړئ') ?></button></form></details></section>
<div class="branch-grid">
<section class="card modern-form"><h3><?= __t('Settle a receivable / payable','دریافت طلب یا پرداخت بدهی','طلب یا پور تصفیه') ?></h3><form method="post"><input type="hidden" name="action" value="create_debt_receipt"><?php payment_common() ?><label><?= __t('Open account','حساب باقی‌دار','پاتې حساب') ?><select class="form-control" name="debt_id" required><?php $q=$pdo->prepare('SELECT id,customer_name,debt_type,remaining_amount,currency_code FROM debts WHERE shop_id=? AND remaining_amount>0 ORDER BY id DESC LIMIT 250');$q->execute([shop_id()]);foreach($q->fetchAll() as $d):?><option value="<?= (int)$d['id'] ?>"><?= sanitize($d['customer_name'].' · '.$d['remaining_amount'].' '.$d['currency_code'].' · '.($d['debt_type']==='payable'?__t('Payable','بدهی','پور'):__t('Receivable','طلب','طلب'))) ?></option><?php endforeach ?></select></label><label><?= __t('Notes','یادداشت','یادښت') ?><textarea class="form-control" name="notes" maxlength="1000"></textarea></label><button class="btn btn-primary"><?= __t('Post settlement','ثبت تسویه','تصفیه ثبت') ?></button></form></section>
<section class="card modern-form"><h3><?= __t('Pay a purchase invoice','پرداخت بل خرید','د پېرود بل تادیه') ?></h3><form method="post"><input type="hidden" name="action" value="create_purchase_payment"><?php payment_common() ?><label><?= __t('Purchase','خرید','پېرود') ?><select class="form-control" name="purchase_id" required><?php $q=$pdo->prepare('SELECT id,reference,total_amount,currency_code FROM inventory_purchases WHERE shop_id=? ORDER BY id DESC LIMIT 250');$q->execute([shop_id()]);foreach($q->fetchAll() as $p):?><option value="<?= (int)$p['id'] ?>"><?= sanitize($p['reference'].' · '.$p['total_amount'].' '.$p['currency_code']) ?></option><?php endforeach ?></select></label><button class="btn btn-primary"><?= __t('Post payment','ثبت پرداخت','تادیه ثبت') ?></button></form></section>
<section class="card modern-form"><h3><?= __t('Pay an unpaid expense','پرداخت مصرف باقی‌دار','د پاتې لګښت تادیه') ?></h3><form method="post"><input type="hidden" name="action" value="create_expense_payment"><?php payment_common() ?><label><?= __t('Expense','مصرف','لګښت') ?><select class="form-control" name="expense_id" required><?php $eq=$pdo->prepare("SELECT e.id,e.description,e.amount,e.currency_code,COALESCE((SELECT SUM(t.amount) FROM fund_transactions t WHERE t.shop_id=e.shop_id AND t.source_type='expense_settlement' AND t.source_id=e.id AND t.direction='out'),0) AS paid FROM ".live_documents_source('expenses','e')." WHERE e.shop_id=? AND EXISTS(SELECT 1 FROM journal_headers h WHERE h.shop_id=e.shop_id AND h.source_type='expense_payable' AND CAST(h.source_id AS SIGNED)=e.id) ORDER BY e.id DESC LIMIT 250");$eq->execute([shop_id()]);foreach($eq->fetchAll() as $expense):$due=dec_sub($expense['amount'],$expense['paid']);if(dec_units($due)<=0)continue;?><option value="<?= (int)$expense['id'] ?>"><?= sanitize('#'.$expense['id'].' · '.$expense['description'].' · '.$due.' '.$expense['currency_code']) ?></option><?php endforeach ?></select></label><button class="btn btn-primary"><?= __t('Post payment','ثبت پرداخت','تادیه ثبت') ?></button></form></section>
<section class="card modern-form"><h3><?= __t('Customer cash refund','برگشت پول مشتری','د پېرودونکي پیسې ستنول') ?></h3><form method="post"><input type="hidden" name="action" value="approve_refund"><?php payment_common() ?><label><?= __t('Outstanding refund','باقی‌ماندهٔ برگشت پول','پاتې ستنول') ?><select class="form-control" name="refund_id" required><?php $q=$pdo->prepare('SELECT r.*,s.invoice_no FROM customer_refunds r JOIN sales s ON s.id=r.sale_id AND s.shop_id=r.shop_id WHERE r.shop_id=? AND r.paid_amount<r.amount ORDER BY r.id DESC');$q->execute([shop_id()]);foreach($q->fetchAll() as $r):?><option value="<?= (int)$r['id'] ?>"><?= sanitize($r['invoice_no'].' · '.dec_sub($r['amount'],$r['paid_amount']).' '.$r['currency_code']) ?></option><?php endforeach ?></select></label><button class="btn btn-primary"><?= __t('Approve refund','تأیید برگشت پول','ستنول تایید') ?></button></form></section>
<section class="card modern-form"><h3><?= __t('Receive supplier refund','دریافت برگشت پول عرضه‌کننده','د عرضه کوونکي پیسې ترلاسه کول') ?></h3><form method="post"><input name="action" type="hidden" value="create_supplier_refund"><?php payment_common() ?><label><?= __t('Returned purchase','خرید برگشت‌شده','ستنول شوی پېرود') ?><select name="purchase_id" class="form-control" required><?php $rq=$pdo->prepare('SELECT DISTINCT p.id,p.reference,p.currency_code FROM inventory_purchases p JOIN purchase_returns r ON r.purchase_id=p.id AND r.shop_id=p.shop_id WHERE p.shop_id=? ORDER BY p.id DESC');$rq->execute([shop_id()]);foreach($rq->fetchAll() as $p):?><option value="<?= (int)$p['id'] ?>"><?= sanitize($p['reference'].' · '.$p['currency_code']) ?></option><?php endforeach ?></select></label><button class="btn btn-primary"><?= __t('Record receipt','ثبت دریافت','رسید ثبت') ?></button></form></section>
<section class="card modern-form"><h3><?= __t('Transfer money','انتقال پول','پیسې لېږدول') ?></h3><form method="post"><input type="hidden" name="action" value="approve_transfer"><?php payment_common() ?><label><?= __t('Destination account & branch','حساب و شعبهٔ گیرنده','د ترلاسه حساب او څانګه') ?><select class="form-control" name="destination" required><option value=""><?= __t('Choose an account','حساب را انتخاب کنید','حساب وټاکئ') ?></option><?php foreach(domain_branches(auth_user()) as $branch):if(!domain_can('treasury.approve',auth_user(),(int)$branch['id']))continue;$dq=$pdo->prepare("SELECT id,name,currency_code FROM fund_accounts WHERE shop_id=? AND status='active' ORDER BY name");$dq->execute([$branch['id']]);?><optgroup label="<?= sanitize($branch['name']) ?>"><?php foreach($dq->fetchAll() as $account):?><option value="<?= (int)$branch['id'].':'.(int)$account['id'] ?>"><?= sanitize($account['name'].' · '.$account['currency_code']) ?></option><?php endforeach ?></optgroup><?php endforeach ?></select></label><button class="btn btn-primary"><?= __t('Approve transfer','تأیید انتقال','لېږد تایید') ?></button></form></section>
</div>
<section class="card modern-form table-responsive"><h3><?= __t('Latest payments & receipts','پرداخت‌ها و دریافت‌های اخیر','وروستۍ تادیې او رسیدونه') ?></h3><table class="table"><thead><tr><?php foreach([__t('Date','تاریخ','نېټه'),__t('Reference','مرجع','شمېره'),__t('Account','حساب','حساب'),__t('Direction','جهت','لوری'),__t('Amount','مبلغ','مبلغ')] as $h):?><th><?= $h ?></th><?php endforeach ?></tr></thead><tbody><?php foreach($history as $t):?><tr><td><?= sanitize($t['payment_date']) ?></td><td><?= sanitize($t['reference']) ?></td><td><?= sanitize($t['name'].' #'.$t['account_id']) ?></td><td><?= $t['direction']==='in'?__t('Received','دریافت','ترلاسه'):__t('Paid','پرداخت','ورکړل') ?></td><td><?= sanitize($t['amount'].' '.$t['currency_code']) ?></td></tr><?php endforeach ?></tbody></table></section>
